def make_dept(id, mgr_name):
    mgr = AgentGenome(role='Manager', goal='Lead', backstory='Leader', model_tier='executive')
    return DepartmentGenome(dept_id=id, name=id, mandate='Test', manager=mgr)
def make_company(cid, depts):
    ceo = AgentGenome(role='CEO', goal='Lead', backstory='Boss', model_tier='executive')
    return CompanyGenome(company_id=cid, ceo=ceo, departments=depts)
